package com.dy.artisan3d.ui.screen.main.article.detailimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.dy.artisan3d.data.AppLanguageimport com.dy.artisan3d.data.mapper.toDomainimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleSingleResponseimport com.dy.artisan3d.domain.model.artisan.ArtisanArticleimport com.dy.artisan3d.domain.repository.ArtisanArticleSingleRepositoryimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.launchclass ArtisanArticleDetailViewModel(    private val artisanArticleSingleRepository: ArtisanArticleSingleRepository,    private val appLanguage: AppLanguage,    private val id: Int): ViewModel() {    private val _uiState = MutableStateFlow(ArtisanArticle(0, "", "", "", "", ""))    val uiState = _uiState.asStateFlow()    init {        fetchArticle()    }    fun fetchArticle(){        viewModelScope.launch {            try {                val article = artisanArticleSingleRepository.getByIdArticle(id = id, lang = appLanguage.current)                _uiState.value = article            }catch (e: Exception){            }        }    }}